/** 按 slug 取（模板用） */
export function getIntegration(slug) {
  return INTEGRATIONS.find((i) => i.slug === slug);
}

/** 某通道下的全部条目（索引页按通道分组用） */
export function integrationsInChannel(channelId) {
  return INTEGRATIONS.filter((i) => i.channel === channelId);
}

/** 通道展示元数据 */
export function channelMeta(channelId) {
  return CHANNELS.find((c) => c.id === channelId);
}

/**
 * 页面上「我们能接多少」的口径 —— **必须分开口径写，不得混成一个数**。
 * 口径一：控制台当前可自助建连接的 (通道 × 供应商) 数。
 * 口径二：quick-sms SDK 已实现的短信适配器数（含未开放自助绑定的）。
 */
export const INTEGRATION_STATS = {
  /** 可自助接入的条目总数（本文件条目数 = 6 SMS + 4 EMAIL + 3 WHATSAPP） */
  selfService: INTEGRATIONS.length,
  /** 按通道拆分的自助接入数 —— 凡句子里带了通道名的，必须取这里的数 */
  byChannel: {
    SMS: integrationsInChannel(CHANNEL_SMS).length,
    EMAIL: integrationsInChannel(CHANNEL_EMAIL).length,
    WHATSAPP: integrationsInChannel(CHANNEL_WHATSAPP).length,
  },
  /**
   * quick-sms SDK 的 `OutboundSender` SPI 实现数（2026-10-14 复核实测：两个模块的
   * `META-INF/services/…OutboundSender` 注册行数 = `sms-providers-intl` 9 +
   * `sms-providers-cn` 24 = **33**）。
   *
   * 🔴 **这是「适配器」数，不是「厂商」数** —— 两个方向的误差都存在，所以对外一律写
   *    「SMS adapters in the library」，不写「33 家供应商」：
   *      · 多算：`CustomHttpOutboundSender` 是通用 HTTP 出口、不是某家厂商；
   *        阿里云/腾讯云/华为各自的 `…International` 与国内实现是同一家厂商的两条端点。
   *      · 少算：邮件与 WhatsApp 的发送器在 `octopus/` 的另几个模块里，不在这 33 里。
   *    这是**短信适配器**数，不是「可自助接入的厂商数」，也不适用于邮件/WhatsApp。
   */
  sdkAdapters: 33,
};
